include { MINIMAC4_COMPRESSREF                    } from 'nf-core/minimac4/compressref'
include { MINIMAC4_IMPUTE                         } from 'nf-core/minimac4/impute'
include { GLIMPSE2_LIGATE                         } from 'nf-core/glimpse2/ligate'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_PHASE  } from 'nf-core/bcftools/index'
include { BCFTOOLS_INDEX as BCFTOOLS_INDEX_LIGATE } from 'nf-core/bcftools/index'

workflow VCF_IMPUTE_MINIMAC4 {
    take:
    ch_input   // channel (mandatory): [ [id, chr], vcf, tbi ]
    ch_panel   // channel (mandatory): [ [panel, chr], vcf, tbi ]
    ch_chunks  // channel (optional) : [ [panel, chr], regionout ]
    ch_map     // channel (optional) : [ [panel, chr], map]

    main:

    ch_panel_branched = ch_panel.branch { _meta, file, _index ->
        def name = file.toString()
        vcf: name.matches(/.*\.(vcf|bcf)(\.gz)?$/)
        msav: name.endsWith('.msav')
        other: true
    }

    ch_panel_branched.other.map {
        error("ERROR: ch_panel files must be either VCF/BCF or MSAV.")
    }

    // Compress reference panel to MSAV format
    MINIMAC4_COMPRESSREF(ch_panel_branched.vcf)

    ch_panel_msav = MINIMAC4_COMPRESSREF.out.msav.mix(
        ch_panel_branched.msav.map { meta, file, _index -> [meta, file] }
    )

    // Channel with all reference and chunks informations
    // [ meta, reference panel msav, sites to impute vcf, sites index, region to impute, genetic map ]
    ch_chunks_counts = ch_chunks
        .groupTuple()
        .map { metaPC, regionouts ->
            [metaPC, regionouts.size()]
        }

    ch_panel_impute = ch_panel_msav
        .combine(ch_chunks, by: 0)
        .combine(ch_map, by: 0)
        .combine(ch_chunks_counts, by: 0)

    ch_panel_impute.ifEmpty {
        error("ERROR: join operation resulted in an empty channel. Please provide a valid ch_posfile, ch_chunks and ch_map channel as input.")
    }

    // Prepare input channels for MINIMAC4
    ch_minimac4_input = ch_input
        .combine(ch_panel_impute)
        .map { metaI, target_vcf, target_tbi, metaPC, ref_msav, regionout, map, region_size ->
            def regionoutPadded
            if (regionout.contains(':')) {
                // Handle format like "chr22:1000-2000"
                def chr = regionout.tokenize(':')[0]
                def region = regionout.tokenize(':')[1]
                def start = region.tokenize('-')[0]
                def end = region.tokenize('-')[1]
                def paddedStart = String.format('%010d', start as long)
                def paddedEnd = String.format('%010d', end as long)
                regionoutPadded = "${chr}:${paddedStart}-${paddedEnd}"
            } else {
                // Handle format like "chr22" (no coordinates)
                regionoutPadded = regionout
            }
            [
                metaPC + metaI + ["regionout": regionout, "regionoutPadded": regionoutPadded, "regionSize": region_size],
                target_vcf, target_tbi,
                ref_msav,
                map,
                regionout,
            ]
        }
    // Perform imputation
    MINIMAC4_IMPUTE(ch_minimac4_input, false)

    // Index the output VCF file
    BCFTOOLS_INDEX_PHASE(MINIMAC4_IMPUTE.out.vcf)

    // Ligate all phased files in one and index it
    ligate_input = MINIMAC4_IMPUTE.out.vcf
        .join(
            BCFTOOLS_INDEX_PHASE.out.index,
            failOnMismatch: true,
            failOnDuplicate: true,
        )
        .map { meta, vcf, index ->
            def keysToKeep = meta.keySet() - ['regionout', 'regionoutPadded', 'regionSize']
            [
                groupKey(meta.subMap(keysToKeep), meta.regionSize),
                vcf, index
            ]
        }
        .groupTuple()
        .map { groupKeyObj, vcf, index ->
            // Extract the actual meta from the groupKey
            def meta = groupKeyObj.getGroupTarget()
            [meta, vcf, index]
        }
        .branch { meta, vcf, index ->
            one: vcf.size() == 1
                return [meta, vcf.get(0), index.get(0)]
            more: vcf.size() > 1
                return [meta, vcf, index]
        }

    GLIMPSE2_LIGATE(ligate_input.more)

    BCFTOOLS_INDEX_LIGATE(GLIMPSE2_LIGATE.out.merged_variants)

    // Join imputed and index files
    ch_vcf_index = GLIMPSE2_LIGATE.out.merged_variants.join(
        BCFTOOLS_INDEX_LIGATE.out.index,
        failOnMismatch: true,
        failOnDuplicate: true,
    ).mix(
        ligate_input.one
    )

    emit:
    vcf_index = ch_vcf_index // channel: [ [id, panel, chr], vcf, index ]
}

nextflow_workflow {

    name "Test Subworkflow VCF_IMPUTE_MINIMAC4"
    script "../main.nf"

    config "./nextflow.config"

    workflow "VCF_IMPUTE_MINIMAC4"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/vcf_impute_minimac4"

    tag "minimac4"
    tag "minimac4/compressref"
    tag "minimac4/impute"
    tag "bcftools"
    tag "bcftools/index"
    tag "glimpse2"
    tag "glimpse2/ligate"

    test("Impute with minimac4 one vcf no map, no chunks, panel as vcf") {
        when {
            workflow {
                """
                input[0] = Channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = Channel.of([
                    [id: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = Channel.of([[id: "1000GP", chr: "chr22"], "chr22"])
                input[3] = Channel.of([[id: "1000GP", chr: "chr22"], []])
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.vcf_index.collect{[
                    it[0],
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}
            ).match()
        }
    }

    test("Impute with minimac4 one vcf with map, chunks, panel as vcf") {
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                [
                    [id: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ],[
                    [id: "1000GP", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = channel.of(
                    [[chr: "chr22", id: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", id: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of([
                    [id: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.minimac.map", checkIfExists:true)
                ],[
                    [id: "1000GP", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr21.minimac.map", checkIfExists:true)
                ])
                """
            }
        }

        then {
            assert workflow.success
            assert snapshot(
                workflow.out.vcf_index.collect{[
                    it[0],
                    path(it[1]).getFileName().toString(),
                    path(it[2]).getFileName().toString(),
                    path(it[1]).vcf.summary,
                    path(it[1]).vcf.header.getGenotypeSamples().sort(),
                    path(it[1]).vcf.variantsMD5
                ]}
            ).match()
        }
    }

    test("homo_sapiens - empty channels - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                [
                    [id: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ],[
                    [id: "1000GP", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = channel.of(
                    [[chr: "chr22", id: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", id: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[id: "1000GP", chr: "chr22"], []],
                    [[id: "1000GP", chr: "chr21"], []]
                )
                """
            }
        }
        then {
            assert workflow.success
            assert snapshot(sanitizeOutput(workflow.out)).match()
        }
    }

    test("homo_sapiens - error wrong panel format - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                    [
                        [id: "1000GP", chr: "chr22"],
                        file(params.modules_testdata_base_path + "genomics/homo_sapiens/genome/genetic_map/genome.GRCh38.chr22.minimac.map", checkIfExists:true),
                        []
                    ],
                    [[id: "1000GP", chr: "chr21"],[],[]]
                )
                input[2] = channel.of(
                    [[chr: "chr22", id: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", id: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[id: "1000GP", chr: "chr22"], []],
                    [[id: "1000GP", chr: "chr21"], []]
                )
                """
            }
        }
        then {
            assert workflow.failed
            assert filterNextflowOutput(workflow.stdout + workflow.stderr).contains("ERROR: ch_panel files must be either VCF/BCF or MSAV.")
        }
    }

    test("homo_sapiens - error empty joint - stub") {
        options "-stub"
        when {
            workflow {
                """
                input[0] = channel.of([
                    [id: "NA12878"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/illumina/vcf/NA12878.chr21_22.1X.glimpse2.vcf.gz.csi", checkIfExists:true)
                ])
                input[1] = channel.of(
                [
                    [id: "1000GP", chr: "chr22"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr22.vcf.gz.csi", checkIfExists:true)
                ],[
                    [id: "1000GP_1", chr: "chr21"],
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz", checkIfExists:true),
                    file(params.modules_testdata_base_path + "genomics/homo_sapiens/popgen/1000GP.chr21.vcf.gz.csi", checkIfExists:true)
                ])
                input[2] = channel.of(
                    [[chr: "chr22", id: "1000GP"], "chr22:16570065-16592216"],
                    [[chr: "chr22", id: "1000GP"], "chr22:16592229-16609999"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16570065-16592216"],
                    [[chr: "chr21", id: "1000GP"], "chr21:16592229-16609999"]
                )
                input[3] = channel.of(
                    [[id: "1000GP_1", chr: "chr22"], []], // Wrong panel
                    [[id: "1000GP", chr: "chr21"], []]
                )
                """
            }
        }
        then {
            assert workflow.failed
            assert filterNextflowOutput(workflow.stdout + workflow.stderr).contains("ERROR: join operation resulted in an empty channel. Please provide a valid ch_posfile, ch_chunks and ch_map channel as input.")
        }
    }
}

